/// <summary>
/// new method which will initialize the controller with the service class and method information. It will be called when the batch job is created.
/// </summary>
public void new()
{
    className = classStr(METExciseRegisterAISCleanUpService);
    methodName = methodStr(METExciseRegisterAISCleanUpService, process);
    super(className, methodName, SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// start point of the batch job which will be called by the batch framework. It will call the process method of the service class through reflection.
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    METExciseRegisterAISCleanUpController controller = new METExciseRegisterAISCleanUpController();
    controller.startOperation();
}
